32	  const [mgEmail,     setMgEmail]     = useLocalStorage('cm_mgEmail',    manager.email);
33	  const [mgPhone,     setMgPhone]     = useLocalStorage('cm_mgPhone',    manager.phone);
34	
35	  // Alert preferences
36	  const [alertTime,   setAlertTime]   = useLocalStorage('cm_alertTime',  '07:00');
37	  const [emailAlerts, setEmailAlerts] = useLocalStorage('cm_emailAlerts', true);
38	  const [smsAlerts,   setSmsAlerts]   = useLocalStorage('cm_smsAlerts',  false);
39	  const [smsPhone,    setSmsPhone]    = useLocalStorage('cm_smsPhone',   '');
40	
41	  // AN-ACC
42	  const [anAccRate,   setAnAccRate]   = useLocalStorage('cm_anAccRate',  String(facility.anAccRate));
43	
44	  // ── Alert Recipients ────────────────────────────────────────────────────────
45	  const [emailRecipients, setEmailRecipients] = useLocalStorage('cm_emailRecipients', DEFAULT_EMAIL_RECIPIENTS);
46	  const [smsRecipients,   setSmsRecipients]   = useLocalStorage('cm_smsRecipients',   DEFAULT_SMS_RECIPIENTS);
47	  const [newEmail,        setNewEmail]        = useState('');
48	  const [emailError,      setEmailError]      = useState('');
49	  const [newMobile,       setNewMobile]       = useState('');
50	  const [mobileError,     setMobileError]     = useState('');
51	  const [recipientsSaved, setRecipientsSaved] = useState(false);
52	  const [recipientsSaving, setRecipientsSaving] = useState(false);
53	
54	  // ── Language & Regional ─────────────────────────────────────────────────────
55	  const [language,    setLanguage]    = useLocalStorage('cm_language',    'en-AU');
56	  const [dateFormat,  setDateFormat]  = useLocalStorage('cm_dateFormat',  'DD/MM/YYYY');
57	  const [timezone,    setTimezone]    = useLocalStorage('cm_timezone',    'AEST');
58	  const [showCents,   setShowCents]   = useLocalStorage('cm_showCents',   true);
59	  const [langSaved,   setLangSaved]   = useState(false);
60	  const [langSaving,  setLangSaving]  = useState(false);
61	
62	  function handleSave(e) {
63	    e.preventDefault();
64	    setSaving(true);
65	    setTimeout(() => {
66	      setSaving(false);
67	      setSaved(true);
68	      setTimeout(() => setSaved(false), 3000);
69	    }, 800);
70	  }
71	
72	  // ── Email recipient handlers ──────────────────────────────────────────────
73	  function validateEmail(email) {
74	    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim());
75	  }
76	
77	  function addEmail() {
78	    const trimmed = newEmail.trim();
79	    if (!validateEmail(trimmed)) {
80	      setEmailError('Please enter a valid email address.');
81	      return;
82	    }
83	    if (emailRecipients.length >= 5) {
84	      setEmailError('Maximum 5 email recipients allowed.');
85	      return;
86	    }
87	    if (emailRecipients.some(r => r.email.toLowerCase() === trimmed.toLowerCase())) {
88	      setEmailError('This email address is already in the list.');
89	      return;
90	    }
91	    setEmailRecipients(prev => [...prev, { id: Date.now(), email: trimmed, active: true }]);
92	    setNewEmail('');
93	    setEmailError('');
94	  }
95	
96	  function removeEmail(id) {
97	    setEmailRecipients(prev => prev.filter(r => r.id !== id));
98	  }
99	
100	  function toggleEmail(id) {
101	    setEmailRecipients(prev => prev.map(r => r.id === id ? { ...r, active: !r.active } : r));
102	  }
103	
104	  // ── SMS recipient handlers ────────────────────────────────────────────────
105	  function validateMobile(mobile) {
106	    return /^04\d{2}\s?\d{3}\s?\d{3}$/.test(mobile.trim());
107	  }
108	
109	  function addMobile() {
110	    const trimmed = newMobile.trim();
111	    if (!validateMobile(trimmed)) {
112	      setMobileError('Enter a valid Australian mobile number (04XX XXX XXX).');
113	      return;
114	    }
115	    if (smsRecipients.length >= 3) {
116	      setMobileError('Maximum 3 SMS recipients allowed.');
117	      return;
118	    }
119	    if (smsRecipients.some(r => r.mobile.replace(/\s/g,'') === trimmed.replace(/\s/g,''))) {
120	      setMobileError('This mobile number is already in the list.');
121	      return;
122	    }
123	    setSmsRecipients(prev => [...prev, { id: Date.now(), mobile: trimmed, active: true }]);
124	    setNewMobile('');
125	    setMobileError('');
126	  }
127	
128	  function removeMobile(id) {
129	    setSmsRecipients(prev => prev.filter(r => r.id !== id));
130	  }
131	
132	  function toggleMobile(id) {
133	    setSmsRecipients(prev => prev.map(r => r.id === id ? { ...r, active: !r.active } : r));
134	  }
135	
