157	        <div className="flex items-center gap-2 mb-5 pb-3 border-b border-gray-100">
158	          <Icon className="w-4 h-4 text-[#22c55e]" />
159	          <h2 className="font-semibold text-gray-900">{title}</h2>
160	        </div>
161	        {children}
162	      </div>
163	    );
164	  }
165	
166	  function Field({ label, hint, children }) {
167	    return (
168	      <div>
169	        <label className="block text-xs font-medium text-gray-600 mb-1">{label}</label>
170	        {hint && <p className="text-xs text-gray-400 mb-1.5">{hint}</p>}
171	        {children}
172	      </div>
173	    );
174	  }
175	
176	  function Input({ value, onChange, placeholder, type = 'text', ...rest }) {
177	    return (
178	      <input
179	        type={type}
180	        value={value}
181	        onChange={onChange}
182	        placeholder={placeholder}
183	        {...rest}
184	        className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#22c55e] transition"
185	      />
186	    );
187	  }
188	
189	  function Toggle({ checked, onChange, label }) {
190	    return (
191	      <label className="flex items-center gap-3 cursor-pointer group">
192	        <div className="relative">
