235	    <div className="p-4 md:p-6 max-w-3xl mx-auto">
236	
237	      <div className="mb-6">
238	        <h1 className="text-xl font-bold text-gray-900">Facility Settings</h1>
239	        <p className="text-sm text-gray-500 mt-0.5">Manage your facility configuration and preferences</p>
240	      </div>
241	
242	      <form onSubmit={handleSave}>
243	
244	        {/* ── Facility Details ── */}
245	        <SectionCard icon={Building2} title="Facility Details">
246	          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
247	            <div className="sm:col-span-2">
