7	import { useLocalStorage } from '@/lib/useLocalStorage';
8	
9	// ─── Helpers ─────────────────────────────────────────────────────────────────
10	
11	function toIso(ddmmyyyy) {
12	  const [d, m, y] = ddmmyyyy.split('/');
13	  return `${y}-${m}-${d}`;
14	}
15	
16	function toDisplay(iso) {
17	  if (!iso) return '';
18	  const [y, m, d] = iso.split('-');
19	  return `${d}/${m}/${y}`;
20	}
21	
22	function calcDuration(start, end) {
23	  if (!start || !end) return 0;
24	  const [sh, sm] = start.split(':').map(Number);
25	  const [eh, em] = end.split(':').map(Number);
26	  const mins = (eh * 60 + em) - (sh * 60 + sm);
27	  return mins > 0 ? mins : 0;
28	}
29	
30	function fmtMins(m) {
31	  return `${Math.floor(m / 60)}h ${m % 60}m`;
32	}
33	
34	// ISO week number helper
35	function getWeek(isoDate) {
36	  const d = new Date(isoDate);
37	  const day = d.getDay() || 7;
38	  d.setUTCDate(d.getUTCDate() + 4 - day);
39	  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
40	  return Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
41	}
42	
43	const THIS_WEEK = getWeek('2026-04-02');
44	
45	// CSV template content
46	const CSV_TEMPLATE = `Date (DD/MM/YYYY),Staff Name,Role,Start Time (HH:MM),End Time (HH:MM)
47	02/04/2026,Sarah Chen,RN,07:00,15:00
48	02/04/2026,Jennifer Walsh,EN,07:00,15:00
49	02/04/2026,David Kim,PCW,15:00,23:00
50	`;
51	
52	// ─── Page ─────────────────────────────────────────────────────────────────────
53	
54	export default function ShiftsPage() {
55	  const [shifts, setShifts]     = useLocalStorage('careminutes_shifts', initialShifts);
56	  const [staff]                 = useLocalStorage('careminutes_staff',  initialStaff);
57	  const [form, setForm]         = useState({ staffId: '', date: '02/04/2026', startTime: '', endTime: '' });
58	  const [editId, setEditId]     = useState(null);
59	  const [editForm, setEditForm] = useState({});
60	  const [auditId, setAuditId]   = useState(null);
61	  const [loading, setLoading]   = useState(false);
62	  const [success, setSuccess]   = useState(false);
63	
64	  const selectedStaff = staff.find(s => s.id === form.staffId);
65	  const duration      = calcDuration(form.startTime, form.endTime);
66	
67	  // This week's minutes
68	  const weekShifts = useMemo(() =>
69	    shifts.filter(s => getWeek(s.date) === THIS_WEEK),
70	  [shifts]);
71	  const weekMinutes = weekShifts.reduce((a, s) => a + s.durationMinutes, 0);
72	  const weekTarget  = facility.residentCount * 215 * 7;
73	
74	  // Sorted shifts (newest first)
75	  const sortedShifts = useMemo(() =>
76	    [...shifts].sort((a, b) => b.date.localeCompare(a.date) || a.startTime.localeCompare(b.startTime)),
77	  [shifts]);
78	
79	  // Add shift
80	  function handleAdd(e) {
81	    e.preventDefault();
82	    if (!selectedStaff || !form.startTime || !form.endTime || duration <= 0) return;
83	    setLoading(true);
84	    setTimeout(() => {
85	      const isoDate = toIso(form.date);
86	      setShifts(prev => [...prev, {
87	        id: `custom-${Date.now()}`,
88	        date: isoDate,
89	        staffId: form.staffId,
90	        staffName: selectedStaff.name,
91	        staffType: selectedStaff.role,
92	        startTime: form.startTime,
93	        endTime: form.endTime,
94	        durationMinutes: duration,
95	        employmentType: selectedStaff.employmentType,
96	      }]);
97	      setForm({ staffId: '', date: '02/04/2026', startTime: '', endTime: '' });
98	      setLoading(false);
99	      setSuccess(true);
100	      setTimeout(() => setSuccess(false), 2500);
101	    }, 500);
102	  }
103	
104	  // Delete shift
105	  function handleDelete(id) {
106	    setShifts(prev => prev.filter(s => s.id !== id));
107	  }
108	
109	  // Start edit
110	  function startEdit(shift) {
111	    setEditId(shift.id);
112	    setEditForm({
113	      date: toDisplay(shift.date),
114	      startTime: shift.startTime,
115	      endTime: shift.endTime,
116	    });
117	  }
118	
119	  // Save edit
120	  function saveEdit(id) {
121	    setShifts(prev => prev.map(s => {
122	      if (s.id !== id) return s;
123	      const dur = calcDuration(editForm.startTime, editForm.endTime);
