132	    const url  = URL.createObjectURL(blob);
133	    const a    = document.createElement('a');
134	    a.href = url; a.download = 'careminutes_shift_template.csv'; a.click();
135	    URL.revokeObjectURL(url);
136	  }
137	
138	  // Handle CSV import (parse and add rows)
139	  function handleCSVImport(e) {
140	    const file = e.target.files[0];
141	    if (!file) return;
142	    const reader = new FileReader();
