187	          </button>
188	          <label className="flex items-center gap-1.5 px-3 py-2 text-sm border border-gray-200 rounded-lg text-gray-600 hover:bg-gray-50 transition-colors font-medium cursor-pointer">
189	            <Upload className="w-4 h-4" /> Import CSV
