193	      </div>
194	
195	      {/* ── This Week Summary ── */}
196	      <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 mb-6">
197	        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
198	          <div>
