366	                      </td>
367	                      <td className="px-4 py-2 text-xs text-gray-500">
368	                        {fmtMins(calcDuration(editForm.startTime, editForm.endTime))}
369	                      </td>
370	                      <td className="px-4 py-2">
371	                        <div className="flex gap-1">
372	                          <button onClick={() => saveEdit(shift.id)} className="p-1.5 bg-green-100 text-green-700 rounded hover:bg-green-200 transition-colors" title="Save">
373	                            <Check className="w-3.5 h-3.5" />
