379	                      </td>
380	                    </>
381	                  ) : (
382	                    <>
383	                      <td className="px-4 py-3 text-gray-700 whitespace-nowrap font-medium">{toDisplay(shift.date)}</td>
384	                      <td className="px-4 py-3 text-gray-700">{shift.staffName}</td>
385	                      <td className="px-4 py-3">
386	                        <span className={`px-2 py-0.5 rounded text-xs font-semibold ${
387	                          shift.staffType === 'RN'  ? 'bg-blue-100 text-blue-700'   :
388	                          shift.staffType === 'EN'  ? 'bg-purple-100 text-purple-700' :
389	                          'bg-gray-100 text-gray-600'
390	                        }`}>{shift.staffType}</span>
391	                      </td>
392	                      <td className="px-4 py-3 text-xs text-gray-500">{shift.employmentType}</td>
393	                      <td className="px-4 py-3 text-gray-700">{shift.startTime}</td>
394	                      <td className="px-4 py-3 text-gray-700">{shift.endTime}</td>
395	                      <td className="px-4 py-3 text-gray-700">{fmtMins(shift.durationMinutes)}</td>
396	                      <td className="px-4 py-3">
397	                        <div className="flex gap-1">
398	                          <button onClick={() => setAuditId(shift.id)} className="p-1.5 bg-blue-50 text-blue-600 rounded hover:bg-blue-100 transition-colors" title="Audit trail">
399	                            <ClipboardList className="w-3.5 h-3.5" />
400	                          </button>
