                    </RadialBar>
                    <Tooltip content={<GaugeTooltip />} />
                  </RadialBarChart>
                </ResponsiveContainer>
                <div className="absolute inset-0 flex flex-col items-center justify-center">
                  <span className="text-2xl md:text-3xl font-bold" style={{ color: gaugeColour(compliancePct) }}>
                    {gaugeValue.toFixed(0)}%
                  </span>
                  <span className="text-xs text-gray-400 mt-0.5">compliant</span>
                </div>
              </div>
              <div className="flex-1 space-y-3 w-full">
                <div className="flex items-center gap-3">
                  <span className="w-3 h-3 rounded-full bg-[#22c55e] shrink-0" />
                  <div className="flex-1 min-w-0">
                    <p className="text-xs text-gray-500">Compliant days</p>
                    <p className="font-semibold text-gray-900 text-sm">{q2Period.compliantDays} / {Q2_ELAPSED} days ({formatPct(compliancePct)})</p>
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <span className="w-3 h-3 rounded-full bg-[#ef4444] shrink-0" />
                  <div className="flex-1 min-w-0">
                    <p className="text-xs text-gray-500">Non-compliant days</p>
                    <p className="font-semibold text-gray-900 text-sm">{q2Period.nonCompliantDays} days so far</p>
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <span className="w-3 h-3 rounded-full bg-[#f59e0b] shrink-0" />
                  <div className="flex-1 min-w-0">
                    <p className="text-xs text-gray-500">Projected non-compliant</p>
                    <p className="font-semibold text-gray-900 text-sm">
                      ~{Math.round(projection.nonComplianceRate * Q2_TOTAL_DAYS)} days for full quarter
                    </p>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Penalty Breakdown Table */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden card-hover">
            <div className="px-4 md:px-5 py-4 border-b border-gray-100">
              <h2 className="font-semibold text-gray-900">Penalty Breakdown</h2>
              <p className="text-xs text-gray-400 mt-0.5">Non-compliant days in Q2 2026 so far</p>
            </div>
            {penaltyRows.length === 0 ? (
              <div className="py-12 text-center">
                <CheckCircle className="w-8 h-8 text-green-500 mx-auto mb-2" />
                <p className="text-sm text-gray-500 font-medium">No penalties recorded this quarter</p>
                <p className="text-xs text-gray-400 mt-1">All days compliant so far</p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-sm min-w-[480px]">
                  <thead>
                    <tr className="bg-gray-50 border-b border-gray-100">
                      {['Date','Status','Residents','Penalty/Resident','Total Penalty'].map(h => (
                        <th key={h} className="text-left px-3 md:px-4 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wide whitespace-nowrap">{h}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {penaltyRows.map((row, i) => (
                      <tr key={i} className={`border-b border-gray-50 hover:bg-red-50/30 transition-colors ${i % 2 === 1 ? 'bg-gray-50/40' : ''}`}>
                        <td className="px-3 md:px-4 py-3 font-medium text-gray-900">{row.date}</td>
                        <td className="px-3 md:px-4 py-3">
                          <span className={`px-2 py-0.5 rounded text-xs font-bold ${
                            row.status === 'RED' ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'
                          }`}>{row.status}</span>
                        </td>
                        <td className="px-3 md:px-4 py-3 text-gray-700">{row.residents}</td>
                        <td className="px-3 md:px-4 py-3 text-gray-700">{formatAUD(row.penaltyDay)}</td>
                        <td className="px-3 md:px-4 py-3 font-semibold text-red-600">{formatAUD(row.total)}</td>
                      </tr>
                    ))}
                    <tr className="bg-red-50 border-t border-red-100">
                      <td colSpan={4} className="px-3 md:px-4 py-3 font-semibold text-gray-700">Total Penalties (Q2 so far)</td>
                      <td className="px-3 md:px-4 py-3 font-bold text-red-700">{formatAUD(q2Period.totalPenalty)}</td>
                    </tr>
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>

        {/* ── Right: Recovery Plan + What If ── */}
        <div className="space-y-4 md:space-y-6">

          {/* Recovery Plan */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 md:p-5 card-hover">
            <div className="flex items-center gap-2 mb-4">
              {recovery.isOnTrack
                ? <CheckCircle className="w-4 h-4 text-green-600" />
                : <AlertTriangle className="w-4 h-4 text-amber-600" />
              }
              <h2 className="font-semibold text-gray-900">Recovery Plan</h2>
            </div>
            {recovery.isOnTrack ? (
              <div className="bg-green-50 border border-green-200 rounded-lg p-3">
                <p className="text-sm text-green-700 font-medium">You are on track for Q2 2026! 🎉</p>
                <p className="text-xs text-green-600 mt-1">Continue current staffing levels to maintain compliance.</p>
              </div>
            ) : (
              <div className="space-y-3">
                <div className="bg-amber-50 border border-amber-200 rounded-lg p-3">
                  <p className="text-sm text-amber-800 font-semibold">
                    {Math.round(recovery.additionalMinutesPerDay).toLocaleString()} additional minutes/day needed
                  </p>
                  <p className="text-xs text-amber-700 mt-1">
                    for the remaining {Q2_REMAINING} days to meet Q2 target.
                  </p>
                </div>
                <div className="space-y-2 text-sm">
                  {[
                    { label: 'Q2 total target',    value: `${recovery.targetTotalMinutes.toLocaleString()} min`, colour: 'text-gray-900' },
                    { label: 'Minutes delivered',   value: `${totalMinutesSoFar.toLocaleString()} min`,          colour: 'text-gray-900' },
                    { label: 'Shortfall',           value: `${recovery.shortfallMinutes.toLocaleString()} min`,  colour: 'text-red-600'  },
                    { label: 'Extra shifts needed', value: `~${Math.ceil(recovery.additionalMinutesPerDay / 480)} shifts/day`, colour: 'text-amber-600' },
                  ].map(({ label, value, colour }) => (
                    <div key={label} className="flex justify-between py-1 border-b border-gray-50 last:border-0 gap-2">
                      <span className="text-gray-500 shrink-0">{label}</span>
                      <span className={`font-semibold ${colour}`}>{value}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* What If Scenario */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 md:p-5 card-hover">
            <h2 className="font-semibold text-gray-900 mb-1">What If Scenario</h2>
            <p className="text-xs text-gray-400 mb-4">Slide to see impact of adding extra RN shifts</p>

            <div className="mb-4">
              <div className="flex justify-between items-center mb-2">
                <label className="text-sm font-medium text-gray-700">Extra RN shifts/week</label>
                <span className="text-lg font-bold text-[#22c55e]">{extraShifts}</span>
              </div>
              <input
                type="range"
                min={1} max={10} step={1}
                value={extraShifts}
                onChange={e => setExtraShifts(Number(e.target.value))}
                className="w-full h-2 bg-gray-200 rounded-full appearance-none cursor-pointer accent-[#22c55e]"
              />
              <div className="flex justify-between text-xs text-gray-400 mt-1">
                <span>1</span>
                <span>10</span>
              </div>
            </div>

            <div className="space-y-1 text-sm">
              {[
                { label: 'Additional minutes/week',      value: `${whatIf.additionalMinutesPerWeek.toLocaleString()} min`,           colour: 'text-gray-900' },
                { label: 'Projected compliance',          value: formatPct(whatIf.projectedCompliancePct),                            colour: whatIf.projectedCompliancePct >= 1 ? 'text-green-600' : whatIf.projectedCompliancePct >= 0.85 ? 'text-amber-600' : 'text-red-600' },
                { label: 'Projected non-compliant days',  value: String(whatIf.projectedNonCompliantDays),                            colour: 'text-gray-900' },
                { label: 'Penalty saved',                 value: whatIf.penaltySaved > 0 ? `+ ${formatAUD(whatIf.penaltySaved)}` : '$0.00', colour: whatIf.penaltySaved > 0 ? 'text-green-600' : 'text-gray-400' },
              ].map(({ label, value, colour }) => (
                <div key={label} className="flex justify-between items-center py-2 border-b border-gray-50 last:border-0 gap-2">
                  <span className="text-gray-500 shrink-0 text-xs">{label}</span>
                  <span className={`font-bold text-sm ${colour}`}>{value}</span>
                </div>
              ))}
            </div>

            {whatIf.projectedCompliancePct >= 1 && (
              <div className="mt-4 bg-green-50 border border-green-200 rounded-lg p-3">
                <p className="text-xs text-green-700 font-medium flex items-center gap-1.5">
                  <TrendingUp className="w-3.5 h-3.5 shrink-0" />
                  Adding {extraShifts} extra RN shift{extraShifts > 1 ? 's' : ''}/week would achieve full Q2 compliance.
                </p>
              </div>
            )}
          </div>

        </div>
      </div>
    </div>
  );
}

input.content:
'use client';

import { useState } from 'react';
import { Bell, CheckCircle, AlertTriangle, Mail, RefreshCw, Zap, X } from 'lucide-react';
import { alerts as initialAlerts } from '@/lib/dummyData';

function formatDate(iso) {
  const [y, m, d] = iso.split('-');
  return `${d}/${m}/${y}`;
}

function Toast({ toast, onDismiss }) {
  if (!toast) return null;
  const isError = toast.type === 'error';
  return (
    <div
      className={`fixed bottom-24 md:bottom-6 left-4 right-4 md:left-1/2 md:right-auto md:-translate-x-1/2 z-50 flex items-start gap-3 px-4 py-3.5 rounded-xl shadow-lg border text-sm font-medium md:max-w-sm transition-all
        ${isError
          ? 'bg-red-50 border-red-200 text-red-800'
          : 'bg-green-50 border-green-200 text-green-800'
        }`}
    >
      {isError
        ? <AlertTriangle className="w-4 h-4 shrink-0 mt-0.5 text-red-500" />
        : <CheckCircle className="w-4 h-4 shrink-0 mt-0.5 text-green-600" />
      }
      <span className="flex-1">{toast.message}</span>
      <button onClick={onDismiss} className="shrink-0 opacity-60 hover:opacity-100 transition-opacity ml-1">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
}

export default function AlertsPage() {
  const [alerts, setAlerts]         = useState(initialAlerts);
  const [generating, setGenerating] = useState(false);
  const [generated, setGenerated]   = useState(false);
  const [toast, setToast]           = useState(null);

  function showToast(message, type = 'success') {
    setToast({ message, type });
    setTimeout(() => setToast(null), 5000);
  }

  async function handleGenerate() {
    setGenerating(true);
    setGenerated(false);

    try {
      const res = await fetch('/api/alerts/send', { method: 'POST' });
      const data = await res.json();

      if (!res.ok || data.error) {
        throw new Error(data.error || 'Failed to send alert.');
      }

      setAlerts(prev => [data.alert, ...prev]);
      setGenerated(true);
      showToast(`Alert sent to ${data.toEmail}`);
      setTimeout(() => setGenerated(false), 3000);
    } catch (err) {
      showToast(err.message || 'Failed to send alert. Please try again.', 'error');
    } finally {
      setGenerating(false);
    }
  }

  const onTrackCount = alerts.filter(a => a.status === 'On Track').length;
  const actionCount  = alerts.filter(a => a.status === 'Action Needed').length;

  return (
    <div className="p-4 md:p-6 max-w-4xl mx-auto">

      {/* ── Header ── */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-6">
        <div>
          <h1 className="text-xl font-bold text-gray-900">AI Shift Gap Alerts</h1>
          <p className="text-sm text-gray-500 mt-0.5">Daily compliance analysis — sent at 07:00 AEST</p>
        </div>
        <button
          onClick={handleGenerate}
          disabled={generating}
          className="flex items-center justify-center gap-2 px-4 py-2.5 bg-[#1e293b] text-white rounded-lg text-sm font-semibold hover:bg-slate-700 active:bg-slate-800 transition-colors disabled:opacity-60 w-full sm:w-auto"
        >
          {generating ? (
            <><RefreshCw className="w-4 h-4 animate-spin" /> Sending alert…</>
          ) : generated ? (
            <><CheckCircle className="w-4 h-4" /> Alert Sent!</>
          ) : (
            <><Zap className="w-4 h-4" /> Generate Alert Now</>
          )}
        </button>
      </div>

      {/* Summary */}
      <div className="grid grid-cols-3 gap-3 md:gap-4 mb-6">
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-3 md:p-4 card-hover">
          <p className="text-xs text-gray-500 uppercase tracking-wide">Total Alerts</p>
          <p className="text-xl md:text-2xl font-bold text-gray-900 mt-1">{alerts.length}</p>
          <p className="text-xs text-gray-400 mt-0.5">Last 7 days</p>
        </div>
        <div className="stat-gradient-green rounded-xl shadow-sm border border-gray-100 p-3 md:p-4 card-hover">
          <p className="text-xs text-gray-500 uppercase tracking-wide">On Track</p>
          <p className="text-xl md:text-2xl font-bold text-green-600 mt-1">{onTrackCount}</p>
        </div>
        <div className="stat-gradient-amber rounded-xl shadow-sm border border-gray-100 p-3 md:p-4 card-hover">
          <p className="text-xs text-gray-500 uppercase tracking-wide">Action Needed</p>
          <p className="text-xl md:text-2xl font-bold text-amber-600 mt-1">{actionCount}</p>
        </div>
      </div>

      {/* Alerts List */}
      <div className="space-y-3 md:space-y-4">
        {alerts.map(alert => (
          <div
            key={alert.id}
            className={`bg-white rounded-xl shadow-sm border overflow-hidden card-hover ${
              alert.status === 'Action Needed' ? 'border-amber-200' : 'border-gray-100'
            }`}
          >
            {/* Card header */}
            <div className={`px-4 md:px-5 py-3 flex items-start justify-between gap-3 ${
              alert.status === 'Action Needed' ? 'bg-amber-50' : 'bg-green-50'
            }`}>
              <div className="flex items-start gap-2 flex-wrap min-w-0">
                {alert.status === 'Action Needed'
                  ? <AlertTriangle className="w-4 h-4 text-amber-600 shrink-0 mt-0.5" />
                  : <CheckCircle className="w-4 h-4 text-green-600 shrink-0 mt-0.5" />
                }
                <span className="text-sm font-semibold text-gray-900 break-words">{alert.title}</span>
                <span className={`px-2 py-0.5 rounded-full text-xs font-bold shrink-0 ${
                  alert.status === 'Action Needed'
                    ? 'bg-amber-200 text-amber-800'
                    : 'bg-green-200 text-green-800'
                }`}>
                  {alert.status}
                </span>
              </div>
              <div className="flex items-center gap-2 shrink-0 flex-wrap justify-end">
                <span className="text-xs text-gray-500 whitespace-nowrap">{formatDate(alert.date)}</span>
                {alert.sentViaEmail && (
                  <span className="flex items-center gap-1 px-2 py-0.5 bg-blue-100 text-blue-700 rounded-full text-xs font-medium whitespace-nowrap">
                    <Mail className="w-3 h-3" /> Email
                  </span>
                )}
              </div>
            </div>

            {/* Card body */}
            <div className="px-4 md:px-5 py-4 space-y-3 md:space-y-4">
              {/* AI message */}
              <div className="flex gap-3">
                <div className="w-7 h-7 rounded-full bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center shrink-0 mt-0.5">
                  <Zap className="w-3.5 h-3.5 text-white" />
                </div>
                <div className="min-w-0">
                  <p className="text-xs font-semibold text-gray-500 mb-1">CareMinutes AI Analysis</p>
                  <p className="text-sm text-gray-700 leading-relaxed">{alert.message}</p>
                </div>
              </div>

              {/* Gaps */}
              {alert.gaps && alert.gaps.length > 0 && (
                <div className="bg-red-50 border border-red-100 rounded-lg p-3">
                  <p className="text-xs font-semibold text-red-700 mb-2 uppercase tracking-wide">Identified Gaps</p>
                  <ul className="space-y-1">
                    {alert.gaps.map((gap, i) => (
                      <li key={i} className="text-xs text-red-700 flex items-start gap-1.5">
                        <span className="mt-0.5 shrink-0">•</span>
                        <span>{gap}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              {/* Suggested staff */}
              {alert.suggestedStaff && alert.suggestedStaff.length > 0 && (
                <div className="bg-blue-50 border border-blue-100 rounded-lg p-3">
                  <p className="text-xs font-semibold text-blue-700 mb-2 uppercase tracking-wide">Suggested Staff to Contact</p>
                  <ul className="space-y-1">
                    {alert.suggestedStaff.map((s, i) => (
                      <li key={i} className="text-xs text-blue-700 flex items-start gap-1.5">
                        <span className="mt-0.5 shrink-0">→</span>
                        <span>{s}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Empty state */}
      {alerts.length === 0 && (
        <div className="text-center py-20">
          <div className="w-16 h-16 rounded-full bg-gray-100 flex items-center justify-center mx-auto mb-4">
            <Bell className="w-8 h-8 text-gray-300" />
          </div>
          <p className="text-gray-500 font-medium">No alerts yet</p>
          <p className="text-sm text-gray-400 mt-1">Alerts are generated daily at 07:00 AEST</p>
        </div>
      )}

      {/* Toast notification */}
      <Toast toast={toast} onDismiss={() => setToast(null)} />
    </div>
  );
}

