    if (!f.name.trim())   e.name  = 'Name is required';
    if (f.phone && !/^04\d{2} \d{3} \d{3}$/.test(f.phone)) e.phone = 'Format: 04XX XXX XXX';
    if (f.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(f.email)) e.email = 'Invalid email address';
    return e;
  }

  function handleAdd(e) {
    e.preventDefault();
    const errs = validate(form);
    if (Object.keys(errs).length) { setErrors(errs); return; }
    setErrors({});
    setLoading(true);
    setTimeout(() => {
      setStaffList(prev => [...prev, {
        id: `staff-new-${Date.now()}`,
        ...form,
        status: 'Active',
      }]);
      setForm(EMPTY_FORM);
      setLoading(false);
      setSuccess(true);
      setTimeout(() => setSuccess(false), 2500);
    }, 500);
  }

  function handleDelete(id) {
    setStaffList(prev => prev.filter(s => s.id !== id));
  }

  function startEdit(s) {
    setEditId(s.id);
    setEditForm({ name: s.name, role: s.role, employmentType: s.employmentType, phone: s.phone, email: s.email });
  }

  function saveEdit(id) {
    const errs = validate(editForm);
    if (Object.keys(errs).length) return;
    setStaffList(prev => prev.map(s => s.id === id ? { ...s, ...editForm } : s));
    setEditId(null);
  }

  return (
    <div className="p-4 md:p-6 max-w-7xl mx-auto">

      {/* ── Header ── */}
      <div className="mb-6">
        <h1 className="text-xl font-bold text-gray-900">Staff Management</h1>
        <p className="text-sm text-gray-500 mt-0.5">Manage your care team</p>
      </div>

      {/* ── Summary Cards ── */}
      <div className="grid grid-cols-3 sm:grid-cols-5 gap-3 mb-6">
        {[
          { label: 'Total',  value: counts.total,  colour: 'text-gray-900',   bg: 'bg-white'      },
          { label: 'RN',     value: counts.rn,     colour: 'text-blue-700',   bg: 'stat-gradient-blue'   },
          { label: 'EN',     value: counts.en,     colour: 'text-purple-700', bg: 'stat-gradient-purple' },
          { label: 'PCW',    value: counts.pcw,    colour: 'text-green-700',  bg: 'stat-gradient-green'  },
          { label: 'Agency', value: counts.agency, colour: 'text-amber-700',  bg: 'stat-gradient-amber'  },
        ].map(({ label, value, colour, bg }) => (
          <div key={label} className={`${bg} rounded-xl border border-gray-100 shadow-sm p-3 md:p-4 card-hover`}>
            <p className="text-xs font-medium text-gray-500">{label}</p>
            <p className={`text-xl md:text-2xl font-bold mt-1 ${colour}`}>{value}</p>
          </div>
        ))}
      </div>

      {/* ── Add Staff Form ── */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 md:p-5 mb-6">
        <h2 className="font-semibold text-gray-900 mb-4 flex items-center gap-2">
          <Plus className="w-4 h-4 text-green-600" /> Add New Staff Member
        </h2>
        <form onSubmit={handleAdd} className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-3 md:gap-4">
          {/* Full name */}
          <div className="sm:col-span-2 lg:col-span-2">
            <label className="block text-xs font-medium text-gray-600 mb-1">Full Name *</label>
            <input
              type="text"
              value={form.name}
              onChange={e => setForm(f => ({ ...f, name: e.target.value }))}
              placeholder="e.g. Sarah Chen"
              className={`w-full border rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-green-500 ${errors.name ? 'border-red-300' : 'border-gray-200'}`}
            />
            {errors.name && <p className="text-xs text-red-500 mt-0.5">{errors.name}</p>}
          </div>

          {/* Role */}
          <div>
            <label className="block text-xs font-medium text-gray-600 mb-1">Role *</label>
            <select
              value={form.role}
              onChange={e => setForm(f => ({ ...f, role: e.target.value }))}
              className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-green-500 bg-white"
            >
              {ROLES.map(r => <option key={r} value={r}>{r}</option>)}
            </select>
          </div>

          {/* Employment type */}
          <div>
            <label className="block text-xs font-medium text-gray-600 mb-1">Employment Type *</label>
            <select
              value={form.employmentType}
              onChange={e => setForm(f => ({ ...f, employmentType: e.target.value }))}
              className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-green-500 bg-white"
            >
              {TYPES.map(t => <option key={t} value={t}>{t}</option>)}
            </select>
          </div>

          {/* Phone */}
          <div>
            <label className="block text-xs font-medium text-gray-600 mb-1">Phone</label>
            <input
              type="text"
              value={form.phone}
              onChange={e => setForm(f => ({ ...f, phone: e.target.value }))}
              placeholder="0411 222 333"
              className={`w-full border rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-green-500 ${errors.phone ? 'border-red-300' : 'border-gray-200'}`}
            />
            {errors.phone && <p className="text-xs text-red-500 mt-0.5">{errors.phone}</p>}
          </div>

          {/* Email */}
          <div className="sm:col-span-2 lg:col-span-2">
            <label className="block text-xs font-medium text-gray-600 mb-1">Email Address</label>
            <input
              type="email"
              value={form.email}
              onChange={e => setForm(f => ({ ...f, email: e.target.value }))}
              placeholder="name@facility.com.au"
              className={`w-full border rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-green-500 ${errors.email ? 'border-red-300' : 'border-gray-200'}`}
            />
            {errors.email && <p className="text-xs text-red-500 mt-0.5">{errors.email}</p>}
          </div>

          {/* Submit */}
          <div className="sm:col-span-2 lg:col-span-5">
            <button
              type="submit"
              disabled={loading}
              className="flex items-center justify-center gap-2 px-5 py-2 bg-[#22c55e] text-white rounded-lg text-sm font-semibold hover:bg-green-600 active:bg-green-700 transition-colors disabled:opacity-60 w-full sm:w-auto"
            >
              {loading ? (
                <span className="flex items-center gap-1.5"><span className="w-3 h-3 border-2 border-white border-t-transparent rounded-full animate-spin" /> Adding…</span>
              ) : success ? (
                <span className="flex items-center gap-1.5"><Check className="w-4 h-4" /> Staff Member Added!</span>
              ) : (
                <span className="flex items-center gap-1.5"><UserCheck className="w-4 h-4" /> Add Staff Member</span>
              )}
            </button>
          </div>
        </form>
      </div>

      {/* ── Filter buttons ── */}
      <div className="flex gap-2 mb-4 flex-wrap">
        {FILTERS.map(f => (
          <button
            key={f}
            onClick={() => setFilter(f)}
            className={`px-4 py-1.5 rounded-full text-sm font-medium transition-colors border ${
              filter === f
                ? 'bg-[#1e293b] text-white border-[#1e293b]'
                : 'bg-white text-gray-600 border-gray-200 hover:border-gray-300 hover:bg-gray-50'
            }`}
          >
            {f} {f !== 'All' && <span className="ml-1 opacity-70">({counts[f.toLowerCase()]})</span>}
          </button>
        ))}
      </div>

      {/* ── Staff Table ── */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm min-w-[600px]">
            <thead>
              <tr className="bg-gray-50 border-b border-gray-200">
                {['Name','Role','Type','Phone','Email','Status','Actions'].map(h => (
                  <th key={h} className="text-left px-3 md:px-4 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wide whitespace-nowrap">
                    {h}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {filtered.length === 0 ? (
                <tr>
                  <td colSpan={7} className="text-center text-gray-400 py-12 text-sm">
                    No staff found.
                  </td>
                </tr>
              ) : filtered.map((s, idx) => (
                <tr key={s.id} className={`border-b border-gray-50 transition-colors hover:bg-green-50/30 ${idx % 2 === 1 ? 'bg-gray-50/40' : ''}`}>
                  {editId === s.id ? (
                    <>
                      <td className="px-3 md:px-4 py-2">
                        <input value={editForm.name} onChange={e => setEditForm(f => ({ ...f, name: e.target.value }))} className="border border-gray-200 rounded px-2 py-1 text-xs w-32" />
                      </td>
                      <td className="px-3 md:px-4 py-2">
                        <select value={editForm.role} onChange={e => setEditForm(f => ({ ...f, role: e.target.value }))} className="border border-gray-200 rounded px-2 py-1 text-xs bg-white">
                          {ROLES.map(r => <option key={r}>{r}</option>)}
                        </select>
                      </td>
                      <td className="px-3 md:px-4 py-2">
                        <select value={editForm.employmentType} onChange={e => setEditForm(f => ({ ...f, employmentType: e.target.value }))} className="border border-gray-200 rounded px-2 py-1 text-xs bg-white">
                          {TYPES.map(t => <option key={t}>{t}</option>)}
                        </select>
                      </td>
                      <td className="px-3 md:px-4 py-2">
                        <input value={editForm.phone} onChange={e => setEditForm(f => ({ ...f, phone: e.target.value }))} className="border border-gray-200 rounded px-2 py-1 text-xs w-28" placeholder="04XX XXX XXX" />
                      </td>
                      <td className="px-3 md:px-4 py-2">
                        <input type="email" value={editForm.email} onChange={e => setEditForm(f => ({ ...f, email: e.target.value }))} className="border border-gray-200 rounded px-2 py-1 text-xs w-36" />
                      </td>
                      <td className="px-3 md:px-4 py-2">
                        <span className="px-2 py-0.5 bg-green-100 text-green-700 rounded text-xs font-medium">Active</span>
                      </td>
                      <td className="px-3 md:px-4 py-2">
                        <div className="flex gap-1">
                          <button onClick={() => saveEdit(s.id)} className="p-1.5 bg-green-100 text-green-700 rounded hover:bg-green-200 transition-colors">
                            <Check className="w-3.5 h-3.5" />
                          </button>
                          <button onClick={() => setEditId(null)} className="p-1.5 bg-gray-100 text-gray-500 rounded hover:bg-gray-200 transition-colors">
                            <X className="w-3.5 h-3.5" />
                          </button>
                        </div>
                      </td>
                    </>
                  ) : (
                    <>
                      <td className="px-3 md:px-4 py-3 font-medium text-gray-900 whitespace-nowrap">{s.name}</td>
                      <td className="px-3 md:px-4 py-3">
                        <span className={`px-2 py-0.5 rounded text-xs font-semibold ${roleBadge(s.role)}`}>{s.role}</span>
                      </td>
                      <td className="px-3 md:px-4 py-3">
                        <span className={`px-2 py-0.5 rounded text-xs font-medium ${typeBadge(s.employmentType)}`}>{s.employmentType}</span>
                      </td>
                      <td className="px-3 md:px-4 py-3 text-gray-600 whitespace-nowrap">{s.phone || '—'}</td>
                      <td className="px-3 md:px-4 py-3 text-gray-600 max-w-[160px] truncate">{s.email || '—'}</td>
                      <td className="px-3 md:px-4 py-3">
                        <span className={`px-2 py-0.5 rounded text-xs font-medium ${s.status === 'Active' ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-500'}`}>
                          {s.status}
                        </span>
                      </td>
                      <td className="px-3 md:px-4 py-3">
                        <div className="flex gap-1">
                          <button onClick={() => startEdit(s)} className="p-1.5 bg-amber-50 text-amber-600 rounded hover:bg-amber-100 transition-colors" title="Edit">
                            <Pencil className="w-3.5 h-3.5" />
                          </button>
                          <button onClick={() => handleDelete(s.id)} className="p-1.5 bg-red-50 text-red-600 rounded hover:bg-red-100 transition-colors" title="Delete">
                            <Trash2 className="w-3.5 h-3.5" />
                          </button>
                        </div>
                      </td>
                    </>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

input.content:
'use client';

import { useState, useEffect, useCallback } from 'react';
import { Bell, CheckCircle, AlertTriangle, Mail, RefreshCw, Zap, X, Database } from 'lucide-react';
import { alerts as dummyAlerts } from '@/lib/dummyData';
import { getAlerts, saveAlert, mapAlert } from '@/lib/db';
import { SEED_FACILITY_ID } from '@/lib/seedData';

function formatDate(iso) {
  const [y, m, d] = iso.split('-');
  return `${d}/${m}/${y}`;
}

function Toast({ toast, onDismiss }) {
  if (!toast) return null;
  const isError = toast.type === 'error';
  return (
    <div className={`fixed bottom-24 md:bottom-6 left-4 right-4 md:left-1/2 md:right-auto md:-translate-x-1/2 z-50 flex items-start gap-3 px-4 py-3.5 rounded-xl shadow-lg border text-sm font-medium md:max-w-sm transition-all
      ${isError ? 'bg-red-50 border-red-200 text-red-800' : 'bg-green-50 border-green-200 text-green-800'}`}
    >
      {isError
        ? <AlertTriangle className="w-4 h-4 shrink-0 mt-0.5 text-red-500" />
        : <CheckCircle  className="w-4 h-4 shrink-0 mt-0.5 text-green-600" />
      }
      <span className="flex-1">{toast.message}</span>
      <button onClick={onDismiss} className="shrink-0 opacity-60 hover:opacity-100 transition-opacity ml-1">
        <X className="w-4 h-4" />
      </button>
    </div>
  );
}

export default function AlertsPage() {
  const [alerts, setAlerts]         = useState(dummyAlerts);
  const [usingDb, setUsingDb]       = useState(false);
  const [dbLoading, setDbLoading]   = useState(true);
  const [generating, setGenerating] = useState(false);
  const [generated, setGenerated]   = useState(false);
  const [toast, setToast]           = useState(null);

  // ── Load alerts from Supabase ───────────────────────────────────────────────
  const loadFromDb = useCallback(async () => {
    setDbLoading(true);
    try {
      const { data, error } = await getAlerts(SEED_FACILITY_ID);
      if (!error && data && data.length > 0) {
        setAlerts(data.map(mapAlert));
        setUsingDb(true);
      }
    } catch {
      // keep dummy data
    } finally {
      setDbLoading(false);
    }
  }, []);

  useEffect(() => { loadFromDb(); }, [loadFromDb]);

  function showToast(message, type = 'success') {
    setToast({ message, type });
    setTimeout(() => setToast(null), 5000);
  }

  // ── Generate alert ──────────────────────────────────────────────────────────
  async function handleGenerate() {
    setGenerating(true);
    setGenerated(false);

    try {
      const res  = await fetch('/api/alerts/send', { method: 'POST' });
      const data = await res.json();

      if (!res.ok || data.error) throw new Error(data.error || 'Failed to send alert.');

      const newAlert = data.alert;

      // Save to Supabase if connected
      if (usingDb) {
        const { data: saved } = await saveAlert(SEED_FACILITY_ID, {
          date:           newAlert.date,
          status:         newAlert.status,
          title:          newAlert.title,
          message:        newAlert.message,
          gaps:           newAlert.gaps           ?? [],
          suggestedStaff: newAlert.suggestedStaff ?? [],
          sentViaEmail:   true,
        });
        if (saved) {
          setAlerts(prev => [mapAlert(saved), ...prev]);
          setGenerated(true);
          showToast(`Alert sent to ${data.toEmail} and saved to database`);
          setTimeout(() => setGenerated(false), 3000);
          return;
        }
      }

      // Fallback: add locally
      setAlerts(prev => [newAlert, ...prev]);
      setGenerated(true);
      showToast(`Alert sent to ${data.toEmail}`);
      setTimeout(() => setGenerated(false), 3000);
    } catch (err) {
      showToast(err.message || 'Failed to send alert. Please try again.', 'error');
    } finally {
      setGenerating(false);
    }
  }

  const onTrackCount = alerts.filter(a => a.status === 'On Track').length;
  const actionCount  = alerts.filter(a => a.status === 'Action Needed').length;

  return (
    <div className="p-4 md:p-6 max-w-4xl mx-auto">

      {/* ── Header ── */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-6">
        <div>
          <div className="flex items-center gap-2 flex-wrap">
            <h1 className="text-xl font-bold text-gray-900">AI Shift Gap Alerts</h1>
            {usingDb ? (
              <span className="flex items-center gap-1 px-2 py-0.5 bg-green-100 text-green-700 text-xs font-semibold rounded-full border border-green-200">
                <Database className="w-3 h-3" /> Live DB
              </span>
            ) : (
              <span className="px-2 py-0.5 bg-blue-100 text-blue-700 text-xs font-semibold rounded-full border border-blue-200">Demo Data</span>
            )}
          </div>
          <p className="text-sm text-gray-500 mt-0.5">Daily compliance analysis — sent at 07:00 AEST</p>
        </div>
        <div className="flex gap-2">
          {usingDb && (
            <button onClick={loadFromDb} disabled={dbLoading} className="flex items-center gap-1.5 px-3 py-2 text-sm border border-gray-200 rounded-lg text-gray-600 hover:bg-gray-50 transition-colors disabled:opacity-50">
              <RefreshCw className={`w-4 h-4 ${dbLoading ? 'animate-spin' : ''}`} />
            </button>
          )}
          <button onClick={handleGenerate} disabled={generating}
            className="flex items-center justify-center gap-2 px-4 py-2.5 bg-[#1e293b] text-white rounded-lg text-sm font-semibold hover:bg-slate-700 active:bg-slate-800 transition-colors disabled:opacity-60 flex-1 sm:flex-none">
            {generating
              ? <><RefreshCw className="w-4 h-4 animate-spin" /> Sending alert…</>
              : generated
                ? <><CheckCircle className="w-4 h-4" /> Alert Sent!</>
                : <><Zap className="w-4 h-4" /> Generate Alert Now</>}
          </button>
        </div>
      </div>

      {/* ── Summary ── */}
      <div className="grid grid-cols-3 gap-3 md:gap-4 mb-6">
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-3 md:p-4 card-hover">
          <p className="text-xs text-gray-500 uppercase tracking-wide">Total Alerts</p>
          <p className="text-xl md:text-2xl font-bold text-gray-900 mt-1">{alerts.length}</p>
          <p className="text-xs text-gray-400 mt-0.5">Last 7 days</p>
        </div>
        <div className="stat-gradient-green rounded-xl shadow-sm border border-gray-100 p-3 md:p-4 card-hover">
          <p className="text-xs text-gray-500 uppercase tracking-wide">On Track</p>
          <p className="text-xl md:text-2xl font-bold text-green-600 mt-1">{onTrackCount}</p>
        </div>
        <div className="stat-gradient-amber rounded-xl shadow-sm border border-gray-100 p-3 md:p-4 card-hover">
          <p className="text-xs text-gray-500 uppercase tracking-wide">Action Needed</p>
          <p className="text-xl md:text-2xl font-bold text-amber-600 mt-1">{actionCount}</p>
        </div>
      </div>

      {/* ── Alerts List ── */}
      <div className="space-y-3 md:space-y-4">
        {alerts.map(alert => (
          <div key={alert.id}
            className={`bg-white rounded-xl shadow-sm border overflow-hidden card-hover ${alert.status === 'Action Needed' ? 'border-amber-200' : 'border-gray-100'}`}>
            {/* Card header */}
            <div className={`px-4 md:px-5 py-3 flex items-start justify-between gap-3 ${alert.status === 'Action Needed' ? 'bg-amber-50' : 'bg-green-50'}`}>
              <div className="flex items-start gap-2 flex-wrap min-w-0">
                {alert.status === 'Action Needed'
                  ? <AlertTriangle className="w-4 h-4 text-amber-600 shrink-0 mt-0.5" />
                  : <CheckCircle  className="w-4 h-4 text-green-600  shrink-0 mt-0.5" />
                }
                <span className="text-sm font-semibold text-gray-900 break-words">{alert.title}</span>
                <span className={`px-2 py-0.5 rounded-full text-xs font-bold shrink-0 ${alert.status === 'Action Needed' ? 'bg-amber-200 text-amber-800' : 'bg-green-200 text-green-800'}`}>
                  {alert.status}
                </span>
              </div>
              <div className="flex items-center gap-2 shrink-0 flex-wrap justify-end">
                <span className="text-xs text-gray-500 whitespace-nowrap">{formatDate(alert.date)}</span>
                {alert.sentViaEmail && (
                  <span className="flex items-center gap-1 px-2 py-0.5 bg-blue-100 text-blue-700 rounded-full text-xs font-medium whitespace-nowrap">
                    <Mail className="w-3 h-3" /> Email
                  </span>
                )}
              </div>
            </div>

            {/* Card body */}
            <div className="px-4 md:px-5 py-4 space-y-3 md:space-y-4">
              <div className="flex gap-3">
                <div className="w-7 h-7 rounded-full bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center shrink-0 mt-0.5">
                  <Zap className="w-3.5 h-3.5 text-white" />
                </div>
                <div className="min-w-0">
                  <p className="text-xs font-semibold text-gray-500 mb-1">CareMinutes AI Analysis</p>
                  <p className="text-sm text-gray-700 leading-relaxed">{alert.message}</p>
                </div>
              </div>

              {alert.gaps && alert.gaps.length > 0 && (
                <div className="bg-red-50 border border-red-100 rounded-lg p-3">
                  <p className="text-xs font-semibold text-red-700 mb-2 uppercase tracking-wide">Identified Gaps</p>
                  <ul className="space-y-1">
                    {alert.gaps.map((gap, i) => (
                      <li key={i} className="text-xs text-red-700 flex items-start gap-1.5">
                        <span className="mt-0.5 shrink-0">•</span><span>{gap}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              {alert.suggestedStaff && alert.suggestedStaff.length > 0 && (
                <div className="bg-blue-50 border border-blue-100 rounded-lg p-3">
                  <p className="text-xs font-semibold text-blue-700 mb-2 uppercase tracking-wide">Suggested Staff to Contact</p>
                  <ul className="space-y-1">
                    {alert.suggestedStaff.map((s, i) => (
                      <li key={i} className="text-xs text-blue-700 flex items-start gap-1.5">
                        <span className="mt-0.5 shrink-0">→</span><span>{s}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* ── Empty state ── */}
      {alerts.length === 0 && (
        <div className="text-center py-20">
          <div className="w-16 h-16 rounded-full bg-gray-100 flex items-center justify-center mx-auto mb-4">
            <Bell className="w-8 h-8 text-gray-300" />
          </div>
          <p className="text-gray-500 font-medium">No alerts yet</p>
          <p className="text-sm text-gray-400 mt-1">Alerts are generated daily at 07:00 AEST</p>
        </div>
      )}

      <Toast toast={toast} onDismiss={() => setToast(null)} />
    </div>
  );
}

